update public.spell_catalog set name_ru='Оживление предметов', casting_time='Действие', spell_range='120 футов', area='До числа целей, равного модификатору характеристики заклинаний', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='', damage='По блоку характеристик Оживлённого предмета', effect_summary='Выбираешь немагические непереносимые и незакреплённые предметы не больше Огромного размера. Средний или меньше считается за 1 цель, Большой — за 2, Огромный — за 3. Они становятся Конструктами, ходят сразу после тебя и подчиняются общим мысленным приказам бонусным действием в пределах 500 футов.', upcast='Урон Удара растёт за каждый уровень ячейки выше 5: +1к4 для Среднего или меньше, +1к6 для Большого, +1к12 для Огромного.', notes='Без приказа оживлённый предмет Уклоняется и двигается только ради безопасности. При 0 HP возвращается в форму предмета, остаток урона переносится на сам предмет.', author_description='Мебель наконец получает право участвовать в драке. Волшебники годами учились ради момента, когда шкаф становится тактически полезнее половины группы.', author_comment='Если стул выполняет приказы лучше союзника, не спеши обвинять магию.' where slug='animate-objects';
update public.spell_catalog set name_ru='Оболочка против жизни', casting_time='Действие', spell_range='На себя', area='Эманация радиусом 10 футов', duration='Концентрация, до 1 часа', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Барьер вокруг тебя не позволяет существам, кроме Конструктов и Нежити, проходить или тянуться сквозь него. Через барьер по-прежнему можно атаковать дальнобойным оружием, оружием с Досягаемостью и накладывать заклинания.', upcast='', notes='Если ты двигаешься так, что вынуждаешь затронутое существо пройти сквозь барьер, заклинание заканчивается.', author_description='Десять футов личного пространства, которое большая часть живых существ обязана уважать. Лучшее заклинание для тех, кто уже путешествовал с группой.', author_comment='Нежить и конструкты всё ещё проходят. Даже магия не обещает идеальный сервис.' where slug='antilife-shell';
update public.spell_catalog set name_ru='Магическая рука', casting_time='Действие', spell_range='120 футов', area='Большая магическая рука', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='яичная скорлупа и перчатка', check_type='Сжатый кулак — рукопашная атака заклинанием; Толкающая рука — спасбросок Силы; Хватающая рука — спасбросок Ловкости', damage='Кулак: 5к8 силового. Сжатие: 4к6 + модификатор характеристики заклинаний дробящего', effect_summary='Создаёшь Большую руку с КД 20 и HP, равными твоему максимуму HP. При наложении и затем бонусным действием можешь переместить её до 60 футов и выбрать эффект: ударить, толкнуть Огромное или меньшее существо, схватить его или использовать руку как полуукрытие и труднопроходимую местность для врагов.', upcast='За каждый уровень ячейки выше 5: Кулак +2к8, урон Сжатия +2к6.', notes='Рука не занимает пространство. При 0 HP заклинание заканчивается. Захваченная цель освобождается против Сл твоего спасброска заклинаний.', author_description='Сто двадцать футов дистанции, огромная сияющая ладонь и четыре официальных способа унизить противника. Волшебник наконец нашёл применение жестам рук, понятное всем.', author_comment='Иногда лучший аргумент — это рука размером с лошадь.' where slug='arcane-hand';
update public.spell_catalog set name_ru='Пробуждение', casting_time='8 часов', spell_range='Касание', area='1 подходящий Зверь, Растение или обычное растение', duration='Мгновенно', components=array['В','С','М'], material='агат стоимостью 1000+ зм, расходуется', check_type='', damage='', effect_summary='Цель должна быть Зверем или Растением с Интеллектом 3 или ниже либо обычным растением. Она получает Интеллект 10 и способность говорить на одном известном тебе языке. Обычное растение становится существом типа Растение, получает подвижность и человеческоподобные чувства.', upcast='', notes='Пробуждённая цель Очарована тобой 30 дней или пока ты либо союзники не нанесёте ей урон. После окончания Очарования она сама определяет отношение к тебе.', author_description='Восемь часов, тысяча золотых и куст внезапно понимает, что последние двадцать лет его стригли без согласия. Добро пожаловать в разумную жизнь.', author_comment='Если дерево после тридцати дней больше не хочет с тобой разговаривать, возможно, оно просто быстро учится.' where slug='awaken';
update public.spell_catalog set name_ru='Смертоносное облако', casting_time='Действие', spell_range='120 футов', area='Сфера радиусом 20 футов', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='Спасбросок Телосложения; не чаще 1 раза за ход на существо', damage='5к8 ядом; половина при успехе', effect_summary='Создаёшь сильно заслонённую сферу жёлто-зелёного ядовитого тумана. Существо делает спасбросок при появлении облака, когда облако входит в его пространство, когда оно входит в облако или заканчивает там ход. В начале каждого твоего хода облако отдаляется от тебя на 10 футов.', upcast='+1к8 урона за каждый уровень ячейки выше 5.', notes='Сильный ветер рассеивает облако и заканчивает заклинание. Одно существо делает спасбросок не чаще одного раза за ход.', author_description='Создаёшь двадцатифутовый шар ядовитого тумана, который медленно уходит от тебя. Даже магическое оружие массового поражения знает, от кого стоит держаться подальше.', author_comment='Если ветер несёт облако обратно к партии, это называется обратной связью.' where slug='cloudkill';
update public.spell_catalog set name_ru='Общение', casting_time='1 минута или ритуал', spell_range='На себя', area='На себя', duration='1 минута', components=array['В','С','М'], material='ладан', check_type='', damage='', effect_summary='Связываешься с божеством или его представителем и задаёшь до трёх вопросов, на которые можно ответить да или нет. Ответы правильные, но при недостатке знания возможен ответ «неясно», а Мастер может дать короткую фразу, если одно слово было бы вводящим в заблуждение.', upcast='', notes='Если используешь заклинание больше одного раза до долгого отдыха, каждое применение после первого получает накопительный шанс 25% не дать ответа.', author_description='Три вопроса высшей силе. Жрец получает прямой канал к божеству и всё равно обязан формулировать вопросы так, чтобы не получить «неясно». Справедливость существует.', author_comment='Если бог отвечает «неясно», поздравляю: теперь вы оба одинаково полезны.' where slug='commune';
update public.spell_catalog set name_ru='Общение с природой', casting_time='1 минута или ритуал', spell_range='На себя', area='На открытой местности радиус 3 мили; в естественных пещерах 300 футов', duration='Мгновенно', components=array['В','С'], material=null, check_type='', damage='', effect_summary='Получаешь три выбранных факта об окружающей природной области: места поселений, межпланарных порталов, одного существа CR 10+ подходящего типа по выбору Мастера, наиболее распространённого растения/минерала/Зверя либо водоёмов.', upcast='', notes='Не работает там, где природа заменена застройкой, например в замках и поселениях.', author_description='Друид спрашивает местность, где вода, города, чудовища и порталы. Следопыт обычно знает половину этого потому, что просто смотрел по сторонам.', author_comment='В городе природа отказывается отвечать. В этом мы с ней солидарны.' where slug='commune-with-nature';
update public.spell_catalog set name_ru='Конус холода', casting_time='Действие', spell_range='На себя', area='Конус 60 футов', duration='Мгновенно', components=array['В','С','М'], material='маленький кристаллический или стеклянный конус', check_type='Спасбросок Телосложения', damage='8к8 холодом; половина при успехе', effect_summary='Выбрасываешь конус ледяного воздуха длиной 60 футов. Все существа в области делают спасбросок Телосложения.', upcast='+1к8 урона за каждый уровень ячейки выше 5.', notes='Существо, погибшее от этого заклинания, становится замёрзшей статуей, пока не оттает.', author_description='Шестьдесят футов мгновенной зимы. Всё очень академично до момента, когда кто-то остаётся стоять в виде ледяной статуи.', author_comment='Если нужен памятник врагу, это самый быстрый способ.' where slug='cone-of-cold';
update public.spell_catalog set name_ru='Призыв элементаля', casting_time='Действие', spell_range='60 футов', area='Большой неосязаемый дух', duration='Концентрация, до 10 минут', components=array['В','С'], material=null, check_type='Спасбросок Ловкости; повтор у Опутанной цели в начале каждого хода', damage='Первый провал: 8к8; последующие провалы удерживаемой цели: 4к8 выбранной стихии', effect_summary='Призываешь дух воздуха, земли, огня или воды, определяя тип урона: электричество, звук, огонь или холод. Когда видимое существо входит в пространство духа или начинает ход в 5 футах, можно потребовать спасбросок, если дух никого не удерживает. При провале цель получает 8к8 и становится Опутанной.', upcast='+2к8 к начальному урону за каждый уровень ячейки выше 5.', notes='Дух одновременно удерживает только одну цель. В начале её хода новый провал наносит 4к8, успех снимает Опутанность.', author_description='Большой дух стихии появляется и хватает первого достаточно невезучего посетителя. Друид назовёт это союзом с природой. Цель — похищением.', author_comment='Если элементаль уже кого-то держит, очередь официально закрыта.' where slug='conjure-elemental';
update public.spell_catalog set name_ru='Контакт с иным планом', casting_time='1 минута или ритуал', spell_range='На себя', area='На себя', duration='1 минута', components=array['В'], material=null, check_type='Спасбросок Интеллекта Сл 15 при наложении', damage='При провале: 6к6 психического', effect_summary='Пытаешься связаться с могущественным существом иного плана. При успешном спасброске Интеллекта задаёшь до пяти вопросов и получаешь однословные или короткие ответы. При провале получаешь 6к6 психического урона и становишься Недееспособным до долгого отдыха.', upcast='', notes='Высшее восстановление снимает Недееспособность от провала. Ответы могут быть «да», «нет», «возможно», «никогда», «не относится», «неясно» или короткой фразой.', author_description='Пять вопросов существу из другого мира с предварительной проверкой, выдержит ли твой мозг сам факт разговора. Очень волшебнический способ получить справку.', author_comment='Если за информацией платишь 6к6 психического, библиотекарь внезапно кажется приятным человеком.' where slug='contact-other-plane';
update public.spell_catalog set name_ru='Заражение', casting_time='Действие', spell_range='Касание', area='1 существо', duration='7 дней', components=array['В','С'], material=null, check_type='Спасбросок Телосложения; затем повтор в конце каждого хода до 3 успехов или 3 провалов', damage='11к8 некротического при первом провале', effect_summary='При провале цель получает 11к8 некротического урона и становится Отравленной. Выбираешь характеристику; пока цель Отравлена, она имеет помеху на спасброски этой характеристики. Затем она копит успехи и провалы спасбросков: 3 успеха заканчивают заклинание, 3 провала закрепляют его на 7 дней.', upcast='', notes='Если другой эффект должен снять Отравление, цель сначала делает спасбросок Телосложения; при провале Отравление от этого заклинания не снимается.', author_description='Одно касание, одиннадцать к8 и неделя последствий. Некроманты умеют превращать рукопожатие в медицинскую историю.', author_comment='После такого любой разумный человек начинает ценить дистанционные приветствия.' where slug='contagion';
update public.spell_catalog set name_ru='Создание', casting_time='1 минута', spell_range='30 футов', area='Предмет до куба 5 футов', duration='Особая, зависит от материала', components=array['В','С','М'], material='кисть для рисования', check_type='', damage='', effect_summary='Создаёшь из теневой материи один знакомый тебе предмет растительного или минерального происхождения размером до куба 5 футов. Длительность: растительный материал 24 ч; камень/кристалл 12 ч; драгоценные металлы 1 ч; самоцветы 10 мин; адамантин/мифрил 1 мин.', upcast='+5 футов к стороне максимального куба за каждый уровень ячейки выше 5.', notes='Если предмет состоит из нескольких материалов, используется кратчайшая длительность. Использование созданного предмета как материального компонента другого заклинания заставляет то заклинание провалиться.', author_description='Создаёшь вещь буквально из тени. Чем дороже материал, тем быстрее реальность вспоминает, что ты жульничал.', author_comment='Мифрил на минуту — достаточно, чтобы похвастаться, но недостаточно, чтобы продать честному человеку.' where slug='creation';
update public.spell_catalog set name_ru='Изгнание зла и добра', casting_time='Действие', spell_range='На себя', area='На себя; специальные эффекты касанием или в 5 футах', duration='Концентрация, до 1 минуты', components=array['В','С','М'], material='порошок серебра и железа', check_type='Изгнание: спасбросок Харизмы', damage='', effect_summary='Небожители, Элементали, Феи, Исчадия и Нежить атакуют тебя с помехой. Можно досрочно закончить заклинание действием Магии: касанием снять Одержимость/Очарование/Испуг от таких существ либо попытаться отправить одно видимое существо подходящего типа в 5 футах на его родной план.', upcast='', notes='Если Фея или Нежить не находится на родном плане, Фея отправляется в Страну Фей, Нежить — в Царство Теней.', author_description='Минуту ты становишься крайне неприятным человеком для всего сверхъестественного зоопарка, а потом можешь ещё и выставить кого-нибудь за дверь между мирами.', author_comment='Паладин называет это очищением. Исчадие — очень односторонней миграционной политикой.' where slug='dispel-evil-and-good';
update public.spell_catalog set name_ru='Подчинение личности', casting_time='Действие', spell_range='60 футов', area='1 видимый гуманоид', duration='Концентрация, до 1 минуты', components=array['В','С'], material=null, check_type='Спасбросок Мудрости; с преимуществом в бою; повтор после каждого получения урона', damage='', effect_summary='При провале гуманоид становится Очарованным. Пока вы на одном плане, можешь телепатически отдавать ему команды без действия. Чтобы приказать использовать Реакцию, тратишь собственную Реакцию.', upcast='Ячейка 6: до 10 минут; 7: до 1 часа; 8+: до 8 часов концентрации.', notes='После каждого получения урона цель повторяет спасбросок и при успехе освобождается.', author_description='Берёшь чужую волю в аренду и называешь это Очарованием. Школа магии опять выбрала самое вежливое слово для совершенно невежливого поступка.', author_comment='Если человеку приходится наносить урон, чтобы он снова начал думать сам, отношения уже сложно назвать здоровыми.' where slug='dominate-person';
update public.spell_catalog set name_ru='Сон', casting_time='1 минута', spell_range='Особая', area='1 известное тебе существо на том же плане; посланник — ты или добровольная цель касанием', duration='8 часов', components=array['В','С','М'], material='горсть песка', check_type='Страшный сон: спасбросок Мудрости', damage='Страшный сон при провале: 3к6 психического после пробуждения и отсутствие пользы от отдыха', effect_summary='Посланник впадает в транс, становится Недееспособным со Скоростью 0 и появляется во сне знакомой цели, когда она спит. Можно разговаривать и формировать окружение сна. Можно сделать сон пугающим, передать до 10 слов и заставить цель сделать спасбросок.', upcast='', notes='Если цель бодрствует, посланник знает это и может ждать её сна либо закончить заклинание. Цель идеально помнит сон после пробуждения.', author_description='Восемь часов вторжения в чужой сон ради разговора, спектакля или психологической диверсии. Барды наконец получили театр без возможности зрителя уйти из зала.', author_comment='Если человек заблокировал тебя во сне, магия уже не поможет социальным навыкам.' where slug='dream';
update public.spell_catalog set name_ru='Небесное пламя', casting_time='Действие', spell_range='60 футов', area='Цилиндр радиусом 10 и высотой 40 футов', duration='Мгновенно', components=array['В','С','М'], material='щепотка серы', check_type='Спасбросок Ловкости', damage='5к6 огнём + 5к6 излучением; половина обоих при успехе', effect_summary='Сверху обрушивается вертикальный столб яркого пламени. Все существа в цилиндре делают спасбросок Ловкости.', upcast='+1к6 огнём и +1к6 излучением за каждый уровень ячейки выше 5.', notes='Апкаст увеличивает оба типа урона одновременно.', author_description='Жрец вызывает десять к6 огня и света сверху, чтобы ещё раз доказать: когда священнослужитель говорит о небесной каре, лучше проверить расстояние.', author_comment='Огненный шар хотя бы не утверждает, что у него моральное превосходство.' where slug='flame-strike';
update public.spell_catalog set name_ru='Гейс', casting_time='1 минута', spell_range='60 футов', area='1 видимое существо, понимающее приказ', duration='30 дней', components=array['В'], material=null, check_type='Спасбросок Мудрости', damage='5к10 психического при прямом нарушении приказа, не чаще 1 раза в день', effect_summary='Даёшь словесный приказ выполнить службу или избегать определённого поведения. При провале цель Очарована. Если она действует прямо против приказа, получает 5к10 психического урона, но не чаще одного раза в день.', upcast='Ячейка 7–8: 365 дней. Ячейка 9: длится, пока не будет снято указанным способом.', notes='Цель автоматически преуспевает, если не понимает приказ. Суицидальный приказ немедленно заканчивает заклинание. Снимается Снятием проклятия, Высшим восстановлением или Желанием.', author_description='Месяц магического обязательства с пунктом о штрафе в пять к10 за нарушение договора. Варлоки смотрят на это и впервые чувствуют себя понятыми.', author_comment='Если контракт наносит психический урон, он хотя бы честнее большинства обычных.' where slug='geas';
update public.spell_catalog set name_ru='Высшее восстановление', casting_time='Действие', spell_range='Касание', area='1 существо', duration='Мгновенно', components=array['В','С','М'], material='алмазная пыль стоимостью 100+ зм, расходуется', check_type='', damage='', effect_summary='Снимаешь один выбранный эффект: 1 уровень Истощения; Очарование или Окаменение; проклятие, включая Настройку на проклятый предмет; снижение одной характеристики; снижение максимума HP.', upcast='', notes='Материал расходуется. За одно применение снимается только один пункт из списка.', author_description='Сто золотых алмазной пыли и одна серьёзная проблема перестаёт быть серьёзной. Жрецы опять раздражающе полезны.', author_comment='Главная причина носить алмазы — не богатство, а количество идиотов вокруг.' where slug='greater-restoration';
update public.spell_catalog set name_ru='Освящение', casting_time='24 часа', spell_range='Касание', area='Область радиусом до 60 футов', duration='До рассеивания', components=array['В','С','М'], material='ладан стоимостью 1000+ зм, расходуется', check_type='', damage='', effect_summary='Навсегда наполняешь область святой или нечестивой силой. Выбираешь типы существ из Аберраций, Небожителей, Элементалей, Фей, Исчадий и Нежити, которые не могут добровольно войти и не могут поддерживать здесь Одержимость/Очарование/Испуг. Дополнительно выбираешь один эффект: Храбрость, Тьма, Дневной свет, Покой мёртвых, блок телепортации/планарных переходов, Страх, Сопротивление, Тишина, Языки или Уязвимость.', upcast='', notes='Если выбранный радиус пересекается с уже действующим Освящением, новое заклинание проваливается. Материал расходуется.', author_description='Двадцать четыре часа работы и тысяча золотых, чтобы навсегда объяснить шестидесяти футам земли, кто здесь желанный гость, а кто нет. Жрецы умеют превращать недвижимость в догму.', author_comment='Если освящение занимает сутки, это уже не заклинание. Это ремонт.' where slug='hallow';